SELECT 
FROM gt_investment_monitoring
WHERE org_id = #{orgId}

    AND investment_id = #{investmentId}


    AND monitoring_type = #{monitoringType}


    AND alert_level = #{alertLevel}


    AND monitoring_status = #{monitoringStatus}


    AND monitoring_date >= #{startDate}


    AND monitoring_date <= #{endDate}

ORDER BY monitoring_date DESC

SELECT 
FROM gt_investment_monitoring
WHERE investment_id = #{investmentId} 
AND monitoring_date BETWEEN #{startDate} AND #{endDate}
AND org_id = #{orgId}
ORDER BY monitoring_date ASC

SELECT COALESCE(SUM(value_change), 0)
FROM gt_investment_monitoring
WHERE org_id = #{orgId}

SELECT 'PERFORMANCE_IMPROVEMENT' as recommendationType, CONCAT('建议关注绩效评分低于60分的投资，当前有', COUNT(*), '项') as recommendationReason, COUNT(*) as affectedCount FROM gt_investment_monitoring WHERE performance_score < 60 AND org_id = #{orgId}
UNION ALL
SELECT 'RISK_CONTROL' as recommendationType, CONCAT('建议加强风险控制，当前有', COUNT(*), '项高风险投资') as recommendationReason, COUNT(*) as affectedCount FROM gt_investment_monitoring WHERE risk_score > 80 AND org_id = #{orgId}

SELECT monitoring_id, investment_id, monitoring_date, 'VALUE_CHANGE_ANOMALY' as anomalyType, CONCAT('价值变化异常：', ROUND(value_change_rate * 100, 2), '%') as anomalyDescription, ABS(value_change_rate) as anomalyScore FROM gt_investment_monitoring WHERE ABS(value_change_rate) > 0.15 AND org_id = #{orgId}
UNION ALL
SELECT monitoring_id, investment_id, monitoring_date, 'PERFORMANCE_ANOMALY' as anomalyType, CONCAT('绩效异常：评分', performance_score) as anomalyDescription, (100 - performance_score) as anomalyScore FROM gt_investment_monitoring WHERE performance_score < 40 AND org_id = #{orgId}
ORDER BY anomalyScore DESC
